Q: Preserve inner span tags when splitting text onto multiple lines A: <p>Do not try to split the HTML string. Split the rendered DOM.</p>
<p>I've made the following changes</p>
<p>Using data-original-html instead of data-original-text, because the original markup must be preserved.</p>
<p>I found a TreeWalker, to walk through the real text nodes inside the paragraph, including text inside nested spans.</p>
<p>We need to use Range, to measure and later clone parts of the rendered DOM with <code>range.cloneContents()</code>, which creates valid fragments even when a line starts or ends inside an existing inline element.</p>
<p>I have tried to stay close-ish to your code</p>
<p>It renders like this</p>
<pre><code>&lt;p class=&quot;cmp-parallax-text-highlight__paragraph&quot;&gt;Lorem ipsum dolor &lt;span class=&quot;myClass&quot;&gt;sit amet&lt;/span&gt;, consectetur adipiscing elit. &lt;span class=&quot;myClass&quot;&gt;Quisque fermentum sem magna&lt;/span&gt;, vitae pharetra neque &lt;/p&gt;
</code></pre>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>let cmpParallaxTextHighlight = {
  init: function(el) {
    const _ = this;

    _.element = el;
    _.debugMode = true;
    _.paragraphs = document.querySelectorAll('.cmp-parallax-text-highlight__paragraph');

    _.splitLines();
    _.reRenderOnResize();
  },

  log: function(message, type) {
    const _ = this;

    if (_.debugMode === false) return;

    type = type || 'log';

    switch (type) {
      case 'info':
        console.info(`%cInfo : ${message}`, 'color: #0099ff');
        break;

      default:
        console.log(message);
        break;
    }
  },

  reRenderOnResize: function() {
    const _ = this;

    window.addEventListener('resize', function() {
      _.splitLines();
    });
  },

  splitLines: function() {
    const _ = this;

    _.paragraphs.forEach(function(paragraph) {
      paragraph.dataset.originalHtml ||= paragraph.innerHTML.trim();
      paragraph.innerHTML = paragraph.dataset.originalHtml;

      const words = _.getWordsWithPositions(paragraph);
      const lines = _.groupWordsIntoLines(words);
      const fragments = _.createLineFragments(lines);
      const lineSpans = fragments.map(function(fragment) {
        return _.createLineSpan(fragment);
      });

      paragraph.replaceChildren(...lineSpans);
    });
  },

  getWordsWithPositions: function(paragraph) {
    const words = [];
    const walker = document.createTreeWalker(paragraph, NodeFilter.SHOW_TEXT);
    const regex = /\S+\s*/g;

    while (walker.nextNode()) {
      const node = walker.currentNode;
      const text = node.nodeValue;
      let match;

      regex.lastIndex = 0;

      while ((match = regex.exec(text))) {
        const range = document.createRange();

        range.setStart(node, match.index);
        range.setEnd(node, match.index + match[0].length);

        words.push({
          node: node,
          start: match.index,
          end: match.index + match[0].length,
          top: Math.round(range.getBoundingClientRect().top)
        });
      }
    }

    return words;
  },

  groupWordsIntoLines: function(words) {
    const lines = [];

    words.forEach(function(word) {
      const lastLine = lines[lines.length - 1];

      if (!lastLine || lastLine.top !== word.top) {
        lines.push({
          top: word.top,
          start: word,
          end: word
        });

        return;
      }

      lastLine.end = word;
    });

    return lines;
  },

  createLineFragments: function(lines) {
    return lines.map(function(line) {
      const range = document.createRange();

      range.setStart(line.start.node, line.start.start);
      range.setEnd(line.end.node, line.end.end);

      return range.cloneContents();
    });
  },

  createLineSpan: function(fragment) {
    const line = document.createElement('span');

    line.className = 'cmp-parallax-text-highlight__paragraph_line';
    line.appendChild(fragment);

    return line;
  }
};

cmpParallaxTextHighlight.init();</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>.myClass {
  color: green
}

.cmp-parallax-text-highlight__paragraph_line {
  display: block;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div style="height: 100px; width: 100%"&gt;&lt;/div&gt;

&lt;div class="cmp-parallax-text-highlight" data-component="cmpParallaxTextHighlight"&gt;
  &lt;div class="cmp-parallax-text-highlight__background"&gt;&lt;/div&gt;
  &lt;div class="cmp-parallax-text-highlight__inner_content container"&gt;
    &lt;div class="row"&gt;
      &lt;div class="col-8"&gt;
        &lt;p class="cmp-parallax-text-highlight__paragraph"&gt;Lorem ipsum dolor &lt;span class="myClass"&gt;sit amet&lt;/span&gt;, consectetur adipiscing elit. &lt;span class="myClass"&gt;Quisque fermentum sem magna&lt;/span&gt;, vitae pharetra neque &lt;/p&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  &lt;/div&gt;
&lt;/div&gt;</code></pre>
